(function(){
const $=s=>document.querySelector(s), esc=Pema.esc;
let screen='home', identity=localStorage.getItem('pema-patient-identity')||'P001', toastTimer;
const nav=[['home','⌂','Trang chủ'],['appointments','◷','Lịch hẹn'],['journey','◌','Hành trình'],['messages','♡','Tin nhắn'],['profile','○','Hồ sơ']];
function p(){return Pema.patient(identity)}
function app(content){const patient=p();document.querySelector('#app').innerHTML=`<div class="mobile-app"><header class="mobile-top"><div class="mobile-brand">pema<small>SKIN JOURNEY</small></div><button class="mobile-icon" data-screen="profile">${Pema.initials(patient)}</button></header><main class="mobile-content">${content}</main><nav class="mobile-nav">${nav.map(n=>`<button class="${screen===n[0]?'active':''}" data-screen="${n[0]}"><span>${n[1]}</span>${n[2]}</button>`).join('')}</nav>${toastTimer?`<div class="mobile-toast">${esc(toastTimer)}</div>`:''}</div>`;bind()}
function home(){const x=p();return `<p class="greeting">Chào ${esc(x.name.split(' ').slice(-1)[0])} 👋</p><h1 class="mobile-heading">Làn da của bạn,<br>được Pema ghi nhớ.</h1><section class="mobile-card mobile-hero"><div class="eyebrow">Hành trình đang tiếp diễn</div><h2>${esc(x.plan)}</h2><p>Buổi ${x.completed} / ${x.total} · Cập nhật gần nhất ${Pema.date(x.lastVisit)}</p><button class="btn btn-primary" style="margin-top:14px;font-size:11px" data-screen="journey">Xem hành trình →</button></section><section class="mobile-card"><div class="mobile-card-head"><h3>Lịch hẹn tiếp theo</h3><a data-screen="appointments">Xem tất cả</a></div><div class="next-appt"><div class="calendar-day"><b>20</b><small>Tháng 09</small></div><div><h4>Đánh giá mốc tiếp theo</h4><p>Thứ hai · 10:30 · Phòng khám Pema<br>${esc(x.doctor)} · ${esc(x.concern)}</p></div><span class="arrow">›</span></div></section><section class="mobile-card"><div class="mobile-card-head"><h3>Tiến độ của bạn</h3><a data-screen="journey">Chi tiết</a></div><div class="mobile-progress"><strong>${Math.round(x.completed/x.total*100)}%</strong><div class="progress"><i style="width:${x.completed/x.total*100}%"></i></div><span style="font-size:10px;color:var(--muted)">${x.completed}/${x.total} buổi</span></div><div class="journey-mobile" style="margin-top:16px">${[['✦','Đánh giá'],['◌','Điều trị'],['♡','Chăm sóc'],['✓','Theo dõi']].map((s,i)=>`<div class="journey-step ${i<2?'done':''} ${i===2?'active':''}"><div class="step-icon">${s[0]}</div><span>${s[1]}</span></div>`).join('')}</div></section><section class="mobile-card"><div class="mobile-card-head"><h3>Chăm sóc hôm nay</h3><a data-screen="care">Xem hướng dẫn</a></div>${x.meds.slice(0,2).map(m=>`<div class="care-row"><div class="care-icon">✦</div><div><h4>${esc(m.name)}</h4><p>${esc(m.use)}</p></div><span class="arrow">›</span></div>`).join('')}<div class="notice">${esc(x.aftercare)}</div></section>`}
function appointments(){const x=p();return `<button class="mobile-back" data-screen="home">← Trang chủ</button><h1 class="mobile-page-title">Lịch hẹn</h1><section class="mobile-card"><div class="mobile-card-head"><h3>Sắp tới</h3><span class="chip chip-soft">Đã xác nhận</span></div><div class="next-appt"><div class="calendar-day"><b>20</b><small>Tháng 09</small></div><div><h4>Đánh giá mốc tiếp theo</h4><p>Thứ hai · 10:30 · Pema Clinic<br>${esc(x.doctor)} · ${esc(x.concern)}</p></div></div><button class="btn btn-primary" style="width:100%;justify-content:center;margin-top:16px" data-action="confirm-appointment">Xác nhận tôi sẽ đến</button></section><section class="mobile-card"><div class="mobile-card-head"><h3>Lịch đã qua</h3></div><div class="doc-row"><div class="doc-icon">✓</div><div><strong>Buổi ${Math.max(1,x.completed)} · ${esc(x.procedure)}</strong><small>${Pema.date(x.lastVisit)} · Đã hoàn tất</small></div><span class="arrow">›</span></div><div class="doc-row"><div class="doc-icon">✓</div><div><strong>Tư vấn ban đầu</strong><small>26/07/2026 · Đã hoàn tất</small></div><span class="arrow">›</span></div></section><div class="notice">Nếu bạn cần đổi lịch, hãy nhắn cho đội ngũ Pema trước ít nhất 4 giờ.</div>`}
function journey(){const x=p();return `<button class="mobile-back" data-screen="home">← Trang chủ</button><h1 class="mobile-page-title">Hành trình của bạn</h1><section class="mobile-card"><div class="eyebrow">${esc(x.plan)}</div><h2 style="font:700 21px Fraunces;color:var(--sage2);margin:7px 0 13px">Bạn đã đi được một đoạn đường.</h2><div class="mobile-progress"><strong>${x.completed}/${x.total}</strong><div class="progress"><i style="width:${x.completed/x.total*100}%"></i></div><span style="font-size:10px;color:var(--muted)">buổi</span></div></section><section class="mobile-card"><div class="mobile-card-head"><h3>Dòng thời gian</h3><span class="chip">Đã xác nhận</span></div><div class="mobile-timeline">${x.events.map((e,i)=>`<div class="m-event"><i class="m-dot" style="background:${e.kind==='followup'?'var(--coral)':e.kind==='photo'?'var(--blue)':'var(--sage)'}"></i><div><time>${Pema.date(e.date)}</time><h4>${esc(e.title)}</h4><p>${esc(e.detail)}</p></div></div>`).join('')}</div></section><section class="mobile-card"><div class="mobile-card-head"><h3>Ảnh tiến trình</h3><a data-screen="progress">Mở ảnh →</a></div><div class="mobile-photo-row">${Pema.face('before','Trước điều trị','m-a')}${Pema.face('after','Gần nhất','m-b')}</div><div class="notice">Ảnh minh họa tổng hợp trong prototype. Ảnh thật được bảo vệ theo quyền riêng tư của bạn.</div></section>`}
function progress(){const x=p();return `<button class="mobile-back" data-screen="journey">← Hành trình</button><h1 class="mobile-page-title">Tiến độ & ảnh</h1><section class="mobile-card"><div class="mobile-card-head"><h3>So sánh mốc ảnh</h3><span class="chip chip-soft">Chính diện</span></div><div class="mobile-photo-row">${Pema.face('before','Trước','pm-a')}${Pema.face('after','Gần nhất','pm-b')}</div><div class="notice">Cùng góc chụp, cùng ánh sáng giúp bác sĩ xem thay đổi trong bối cảnh. Không dùng ảnh này để tự chẩn đoán.</div></section><section class="mobile-card"><div class="mobile-card-head"><h3>Gửi ảnh cập nhật</h3></div><div class="upload-box"><div style="font-size:24px">▧</div><p>Bạn có thể gửi ảnh để đội ngũ Pema xem và phản hồi. Tránh gửi thông tin nhận diện không cần thiết.</p><input type="file" accept="image/png,image/jpeg,image/webp" id="progress-photo"><label class="btn btn-primary" for="progress-photo">Chọn ảnh</label><div id="progress-file" style="font-size:10px;margin-top:7px"></div></div></section>`}
function care(){const x=p();return `<button class="mobile-back" data-screen="home">← Trang chủ</button><h1 class="mobile-page-title">Chăm sóc tại nhà</h1><section class="mobile-card"><div class="eyebrow">Sau buổi điều trị</div><h2 style="font:700 20px Fraunces;color:var(--sage2);margin:7px 0 8px">Mỗi ngày một chút dịu dàng.</h2><p class="subtitle">${esc(x.aftercare)}</p>${x.meds.map(m=>`<div class="care-row" style="margin-top:11px"><div class="care-icon">✦</div><div><h4>${esc(m.name)}</h4><p>${esc(m.use)}</p></div></div>`).join('')}</section><section class="mobile-card"><div class="mobile-card-head"><h3>Khi nào cần nhắn Pema?</h3></div><p style="font-size:11px;color:var(--muted);line-height:1.55;margin:0">Nếu bạn thấy phản ứng bất thường, khó chịu kéo dài hoặc cần hỏi cách chăm sóc, hãy gửi cập nhật trong ứng dụng. Đội ngũ sẽ xem và phản hồi theo quy trình của phòng khám.</p><button class="btn btn-primary" style="margin-top:14px" data-screen="send">Gửi cập nhật →</button></section>`}
function send(){return `<button class="mobile-back" data-screen="care">← Chăm sóc tại nhà</button><h1 class="mobile-page-title">Gửi cập nhật cho Pema</h1><section class="mobile-card"><div class="field"><label>Bạn đang cảm thấy thế nào?</label><textarea id="patient-message" placeholder="Ví dụ: Da hơi khô ở hai má từ tối qua..."></textarea></div><div class="upload-box"><div style="font-size:24px">▧</div><p>Thêm ảnh nếu bạn muốn đội ngũ xem vùng da cụ thể.</p><input type="file" accept="image/png,image/jpeg,image/webp" id="patient-photo"><label class="btn" for="patient-photo">Chọn ảnh</label><div id="patient-file" style="font-size:10px;margin-top:7px"></div></div><button class="btn btn-primary" style="width:100%;justify-content:center;margin-top:15px" data-action="send-update">Gửi cho Pema</button><div class="notice">Tin nhắn được gửi tới đội ngũ chăm sóc. Đây không phải kênh cấp cứu.</div></section>`}
function messages(){const x=p();return `<button class="mobile-back" data-screen="home">← Trang chủ</button><h1 class="mobile-page-title">Tin nhắn</h1><section class="mobile-card"><div class="mobile-card-head"><h3>Pema Care Team</h3><span class="status status-green">Đang hỗ trợ</span></div>${x.messages.map(m=>`<div class="message ${m.from==='patient'?'mine':''}">${esc(m.text)}<time>${esc(m.date)}</time></div>`).join('')}<button class="btn btn-primary" style="width:100%;justify-content:center;margin-top:7px" data-screen="send">＋ Gửi tin nhắn</button></section>`}
function docs(){const x=p();return `<button class="mobile-back" data-screen="profile">← Hồ sơ</button><h1 class="mobile-page-title">Tài liệu & hóa đơn</h1><section class="mobile-card"><div class="mobile-card-head"><h3>Hóa đơn của bạn</h3></div>${x.invoices.length?x.invoices.map(i=>`<div class="doc-row"><div class="doc-icon">▤</div><div><strong>${esc(i.label)}</strong><small>${esc(i.id)} · ${esc(i.date)} · ${i.paid?'Đã thanh toán':'Chờ thanh toán'}</small></div><strong style="margin-left:auto;font-size:11px">${Pema.money(i.amount)}</strong></div>`).join(''):'<div class="empty">Chưa có hóa đơn trong demo.</div>'}</section><section class="mobile-card"><div class="mobile-card-head"><h3>Hướng dẫn đã gửi</h3></div><div class="doc-row"><div class="doc-icon">▧</div><div><strong>Hướng dẫn chăm sóc sau buổi</strong><small>PDF · 23/08/2026</small></div><span class="arrow">↓</span></div></section>`}
function profile(){const x=p();return `<h1 class="mobile-page-title">Hồ sơ</h1><section class="mobile-card"><div style="display:flex;gap:13px;align-items:center"><div class="avatar patient-avatar">${Pema.initials(x)}</div><div><h3 style="margin:0 0 4px;font-size:15px">${esc(x.name)}</h3><p style="margin:0;color:var(--muted);font-size:11px">${x.age} tuổi · ${x.phone} · ${x.id}</p></div></div><div class="notice">Bạn đang xem trải nghiệm patient app của hồ sơ demo. Tài khoản và dữ liệu thật sẽ cần xác thực riêng.</div></section><section class="mobile-card"><div class="doc-row" data-screen="docs"><div class="doc-icon">▤</div><div><strong>Tài liệu & hóa đơn</strong><small>Xem lịch sử thanh toán và hướng dẫn</small></div><span class="arrow">›</span></div><div class="doc-row" data-screen="care"><div class="doc-icon">✦</div><div><strong>Chăm sóc tại nhà</strong><small>Hướng dẫn của kế hoạch hiện tại</small></div><span class="arrow">›</span></div><div class="doc-row"><div class="doc-icon">⚙</div><div><strong>Quyền riêng tư</strong><small>Quản lý đồng ý sử dụng ảnh</small></div><span class="arrow">›</span></div></section><section class="mobile-card"><div class="mobile-card-head"><h3>Đổi hồ sơ demo</h3></div><div class="field"><label>Chọn người bệnh tổng hợp</label><select id="identity-select">${Pema.state.patients.slice(0,8).map(q=>`<option value="${q.id}" ${q.id===identity?'selected':''}>${esc(q.name)} · ${q.id}</option>`).join('')}</select></div><p style="font-size:10px;color:var(--muted);margin:0">Chỉ dùng để trình diễn trải nghiệm liên thông; không đại diện đăng nhập thật.</p></section>`}
function render(){Pema.reload();let c=screen==='home'?home():screen==='appointments'?appointments():screen==='journey'?journey():screen==='progress'?progress():screen==='care'?care():screen==='send'?send():screen==='messages'?messages():screen==='docs'?docs():profile();app(c)}
function showToast(msg){toastTimer=msg;render();clearTimeout(window.__toast);window.__toast=setTimeout(()=>{toastTimer='';render()},2800)}
function bind(){document.querySelectorAll('[data-screen]').forEach(b=>b.onclick=()=>{screen=b.dataset.screen;render()});const sel=$('#identity-select');if(sel)sel.onchange=()=>{identity=sel.value;localStorage.setItem('pema-patient-identity',identity);render();showToast('Đã đổi hồ sơ demo')};const pf=$('#progress-photo');if(pf)pf.onchange=()=>{$('#progress-file').textContent=pf.files[0]?pf.files[0].name:''};const pt=$('#patient-photo');if(pt)pt.onchange=()=>{$('#patient-file').textContent=pt.files[0]?pt.files[0].name:''};document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));}
async function action(a){const x=p();if(a==='confirm-appointment'){x.messages.push({from:'clinic',text:'Lịch hẹn ngày 20/09 lúc 10:30 đã được xác nhận. Hẹn gặp bạn tại Pema.',date:'20/09 · vừa xong'});Pema.addEvent(x,'appointment','Người bệnh đã xác nhận lịch hẹn','Xác nhận từ patient app.','Pema Care Team');Pema.save();showToast('Đã xác nhận lịch hẹn');return}if(a==='send-update'){const text=$('#patient-message').value.trim();if(!text){showToast('Hãy viết vài dòng cập nhật');return}const file=$('#patient-photo').files[0];try{if(file)await Pema.imageData(file)}catch(e){showToast(e.message);return}x.messages.push({from:'patient',text,date:'20/09 · vừa xong'});const f={id:'F'+Date.now(),patient:x.id,type:file?'Ảnh cần bác sĩ xem':'Phản hồi từ patient app',priority:'review',symptom:text,date:new Date().toISOString(),image:file?'placeholder':null,status:'open',owner:'BS. Tâm'};Pema.state.followups.unshift(f);Pema.addEvent(x,'followup','Đã gửi cập nhật cho Pema',text,'Patient app');Pema.save();screen='messages';showToast('Đã gửi cập nhật tới đội ngũ Pema');return}}
window.addEventListener('pema-external',()=>{render()});window.addEventListener('pema-change',()=>{if(!toastTimer)render()});render();
})();
